css:
@keyframes solarPlasmaMotion {
  0% {
    background-position: 30% 20%, 75% 60%, 50% 85%;
  }
  50% {
    background-position: 70% 45%, 35% 25%, 65% 55%;
  }
  100% {
    background-position: 30% 20%, 75% 60%, 50% 85%;
  }
}
[data-workspace-area="conversation"] {
  background-color: #0b0406 !important;
  background-image: 
    radial-gradient(circle at 30% 20%, rgba(255, 77, 77, 0.35) 0%, transparent 50%),
    radial-gradient(circle at 75% 60%, rgba(251, 191, 36, 0.28) 0%, transparent 50%),
    radial-gradient(circle at 50% 85%, rgba(225, 29, 72, 0.25) 0%, transparent 60%) !important;
  background-size: 160% 160%, 150% 150%, 170% 170% !important;
  animation: solarPlasmaMotion 18s ease-in-out infinite !important;
}
.chat-markdown-codeblock {
  backdrop-filter: blur(16px) saturate(150%) !important;
  background: rgba(22, 9, 13, 0.76) !important;
  border: 1px solid rgba(255, 77, 77, 0.25) !important;
  box-shadow: 0 8px 30px rgba(255, 77, 77, 0.12) !important;
}
[data-chat-header] {
  backdrop-filter: blur(14px) !important;
  background: rgba(11, 4, 6, 0.8) !important;
  border-bottom: 1px solid rgba(255, 77, 77, 0.18) !important;
}
